      Lemma vs_some : forall msF,
        as_VIS H sA0 msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (wz A_VS_DTOR) fc None m0 (seg_rom asegs) ->
        as_AKREL H sA0 (mkCfg msF mo0) ->
        rw_cells asegs m0 va (hdr9 temp Bg (Bg + 24 * Z.of_nat n) EE chars j7) ->
        rw_cells asegs m0 Bg [CB (24 * n)%nat bs; CB (Z.to_nat (24 * (cap - Z.of_nat n))) junk] ->
        Forall (item_deep m0) items -> addressable m0 Bg (24 * cap) ->
